import java.util.*;

public class Apples {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] x = new long[n];
        long[] y = new long[n];
        long[] u = new long[n];
        long[] v = new long[n];
        for (int i = 0; i < n; i++) {
            x[i] = sc.nextLong();
            y[i] = sc.nextLong();
            u[i] = sc.nextLong();
            v[i] = sc.nextLong();
        }

        int best = Math.min(2, n); // at least 1, but if n>=2 we can always hit 2 at some time

        // Try all triples
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int k = j + 1; k < n; k++) {
                    // Find times t >= 0 when i, j, k are collinear
                    // collinear condition: determinant = 0
                    // (x_i + t*u_i - x_j - t*u_j)*(y_i + t*v_i - y_k - t*v_k) 
                    // = (x_i + t*u_i - x_k - t*u_k)*(y_i + t*v_i - y_j - t*v_j)
                    // This is quadratic in t: a*t^2 + b*t + c = 0
                    long a = (u[i] - u[j]) * (v[i] - v[k]) - (u[i] - u[k]) * (v[i] - v[j]);
                    long b = (u[i] - u[j]) * (y[i] - y[k]) + (x[i] - x[j]) * (v[i] - v[k])
                           - (u[i] - u[k]) * (y[i] - y[j]) - (x[i] - x[k]) * (v[i] - v[j]);
                    long c = (x[i] - x[j]) * (y[i] - y[k]) - (x[i] - x[k]) * (y[i] - y[j]);

                    // Solve a*t^2 + b*t + c = 0
                    List<Double> times = new ArrayList<>();
                    if (a == 0) {
                        if (b == 0) {
                            if (c == 0) {
                                // Always collinear -> check t=0
                                times.add(0.0);
                            }
                        } else {
                            double t = -c / (double) b;
                            if (t >= -1e-12) times.add(t);
                        }
                    } else {
                        long disc = b * b - 4 * a * c;
                        if (disc >= 0) {
                            double sqrtDisc = Math.sqrt(disc);
                            double t1 = (-b - sqrtDisc) / (2.0 * a);
                            double t2 = (-b + sqrtDisc) / (2.0 * a);
                            if (t1 >= -1e-12) times.add(t1);
                            if (t2 >= -1e-12 && Math.abs(t2 - t1) > 1e-12) times.add(t2);
                        }
                    }

                    for (double t : times) {
                        if (t < -1e-12) continue;
                        // Count how many points are on the line defined by i and j at time t
                        // line direction at time t from i: (x[i] + t*u[i], y[i] + t*v[i])
                        double xi = x[i] + t * u[i];
                        double yi = y[i] + t * v[i];
                        double dx = (x[j] + t * u[j]) - xi;
                        double dy = (y[j] + t * v[j]) - yi;
                        int count = 0;
                        for (int p = 0; p < n; p++) {
                            double xp = x[p] + t * u[p];
                            double yp = y[p] + t * v[p];
                            // cross product (xp-xi, yp-yi) x (dx, dy) should be ~0
                            double cross = (xp - xi) * dy - (yp - yi) * dx;
                            if (Math.abs(cross) < 1e-9) count++;
                        }
                        if (count > best) best = count;
                    }
                }
            }
        }

        System.out.println(best);
    }
}

