import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Fraction {
        long num, den; // den > 0, reduced

        Fraction(long num, long den) {
            if (den < 0) {
                num = -num;
                den = -den;
            }
            if (num == 0) {
                this.num = 0;
                this.den = 1;
            } else {
                long g = gcd(Math.abs(num), den);
                this.num = num / g;
                this.den = den / g;
            }
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Fraction)) return false;
            Fraction f = (Fraction) o;
            return num == f.num && den == f.den;
        }

        @Override
        public int hashCode() {
            return (int)(num * 1000003L + den);
        }
    }

    static class LineKey {
        long A, B, C; // normalized line A x + B y + C = 0

        LineKey(long A, long B, long C) {
            this.A = A;
            this.B = B;
            this.C = C;
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof LineKey)) return false;
            LineKey k = (LineKey) o;
            return A == k.A && B == k.B && C == k.C;
        }

        @Override
        public int hashCode() {
            long h = A;
            h = h * 1000003L + B;
            h = h * 1000003L + C;
            return (int)(h ^ (h >>> 32));
        }
    }

    static class Pair {
        int i, j;
        Pair(int i, int j) { this.i = i; this.j = j; }
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return Math.abs(a);
    }

    static LineKey normalizeLine(long x1, long y1, long x2, long y2) {
        long A = y2 - y1;
        long B = x1 - x2;
        long C = -(A * x1 + B * y1);

        long g = gcd(Math.abs(A), gcd(Math.abs(B), Math.abs(C)));
        if (g != 0) {
            A /= g;
            B /= g;
            C /= g;
        }

        if (A < 0 || (A == 0 && B < 0) || (A == 0 && B == 0 && C < 0)) {
            A = -A;
            B = -B;
            C = -C;
        }
        return new LineKey(A, B, C);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        long[] x = new long[N];
        long[] y = new long[N];
        long[] u = new long[N];
        long[] v = new long[N];

        for (int i = 0; i < N; i++) {
            x[i] = fs.nextLong();
            y[i] = fs.nextLong();
            u[i] = fs.nextLong();
            v[i] = fs.nextLong();
        }

        if (N <= 2) {
            System.out.println(N);
            return;
        }

        int answer = 1;

        // For each time t determined by some pair becoming coincident,
        // check the maximum number of points collinear at that time.
        HashMap<Fraction, ArrayList<Pair>> timePairs = new HashMap<>();

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                long dx = x[j] - x[i];
                long dy = y[j] - y[i];
                long du = u[i] - u[j];
                long dv = v[i] - v[j];

                if (du == 0 && dv == 0) {
                    if (dx == 0 && dy == 0) {
                        // Always coincident; at least 2 apples can be hit.
                        answer = Math.max(answer, 2);
                    }
                    continue;
                }

                Fraction t = null;
                boolean ok = true;

                if (du == 0) {
                    if (dx != 0) ok = false;
                } else {
                    t = new Fraction(dx, du);
                }

                if (dv == 0) {
                    if (dy != 0) ok = false;
                } else {
                    Fraction ty = new Fraction(dy, dv);
                    if (t == null) t = ty;
                    else if (!t.equals(ty)) ok = false;
                }

                if (!ok || t == null) continue;
                if (t.num < 0) continue; // t >= 0

                timePairs.computeIfAbsent(t, k -> new ArrayList<>()).add(new Pair(i, j));
            }
        }

        // At each candidate time, compute positions and count max collinear points.
        for (Map.Entry<Fraction, ArrayList<Pair>> entry : timePairs.entrySet()) {
            Fraction t = entry.getKey();
            long tn = t.num, td = t.den;

            long[] X = new long[N];
            long[] Y = new long[N];
            for (int i = 0; i < N; i++) {
                X[i] = x[i] * td + u[i] * tn;
                Y[i] = y[i] * td + v[i] * tn;
            }

            HashMap<LineKey, HashSet<Integer>> linePoints = new HashMap<>();

            for (int i = 0; i < N; i++) {
                for (int j = i + 1; j < N; j++) {
                    if (X[i] == X[j] && Y[i] == Y[j]) continue;
                    LineKey key = normalizeLine(X[i], Y[i], X[j], Y[j]);
                    HashSet<Integer> set = linePoints.computeIfAbsent(key, k -> new HashSet<>());
                    set.add(i);
                    set.add(j);
                }
            }

            for (HashSet<Integer> set : linePoints.values()) {
                answer = Math.max(answer, set.size());
            }

            // Also account for multiple points all coincident with no non-degenerate line needed.
            HashMap<Long, Integer> pointCount = new HashMap<>();
            for (int i = 0; i < N; i++) {
                long hx = X[i] * 1000000007L + Y[i];
                pointCount.put(hx, pointCount.getOrDefault(hx, 0) + 1);
            }
            for (int c : pointCount.values()) answer = Math.max(answer, c);
        }

        // Also check time t = 0.
        {
            HashMap<LineKey, HashSet<Integer>> linePoints = new HashMap<>();
            for (int i = 0; i < N; i++) {
                for (int j = i + 1; j < N; j++) {
                    if (x[i] == x[j] && y[i] == y[j]) continue;
                    LineKey key = normalizeLine(x[i], y[i], x[j], y[j]);
                    HashSet<Integer> set = linePoints.computeIfAbsent(key, k -> new HashSet<>());
                    set.add(i);
                    set.add(j);
                }
            }
            for (HashSet<Integer> set : linePoints.values()) {
                answer = Math.max(answer, set.size());
            }
            HashMap<Long, Integer> pointCount = new HashMap<>();
            for (int i = 0; i < N; i++) {
                long hx = x[i] * 1000000007L + y[i];
                pointCount.put(hx, pointCount.getOrDefault(hx, 0) + 1);
            }
            for (int c : pointCount.values()) answer = Math.max(answer, c);
        }

        System.out.println(answer);
    }
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<ll> x(n), y(n), u(n), v(n);
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> y[i] >> u[i] >> v[i];
    }

    int ans = 1; // at least one apple

    // Try every pair as defining the line at some time t
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            // We want to see if there's a time t >= 0 such that
            // (x_i + t*u_i, y_i + t*v_i) and (x_j + t*u_j, y_j + t*v_j)
            // are collinear with the bullet's path.
            // Actually, if we choose bullet direction = direction from i to j at time t,
            // then everyone on that line at time t is hit.

            // Compute the relative motion
            ll dx = x[j] - x[i];
            ll dy = y[j] - y[i];
            ll du = u[j] - u[i];
            ll dv = v[j] - v[i];

            // We need t such that direction vector (dx + t*du, dy + t*dv) is defined.
            // This always works for any t, but we can pick t that makes i and j on the bullet line.
            // Since bullet can be shot at any t, we can set t=0 and direction = (dx, dy) if du=dv=0.
            // Otherwise we can pick t to maximize count.

            // Actually simpler: For any t, we can shoot along the line connecting them at that t.
            // So we just want to find t >= 0 maximizing collinear points with that pair.

            // For given t, direction from i is (dx + t*du, dy + t*dv).
            // We need to count points k such that cross product = 0:
            // (x_k - x_i + t*(u_k - u_i)) cross (dx + t*du) = 0.

            // Instead of iterating t, we can think: For each k, the condition is linear in t.
            // We can solve for t and count occurrences.

            map<pair<ll,ll>, int> cnt;
            int base = 2; // i and j count
            for (int k = 0; k < n; k++) {
                if (k == i || k == j) continue;
                // Cross product = 0 condition:
                // (dx_k + t*du_k) * (dy + t*dv) - (dy_k + t*dv_k)*(dx + t*du) = 0
                // where dx_k = x_k - x_i, dy_k = y_k - y_i, du_k = u_k - u_i, dv_k = v_k - v_i
                ll dxk = x[k] - x[i];
                ll dyk = y[k] - y[i];
                ll duk = u[k] - u[i];
                ll dvk = v[k] - v[i];

                // Expand:
                // (dxk + t*duk)*(dy + t*dv) - (dyk + t*dvk)*(dx + t*du) = 0
                // = dxk*dy + t*(dxk*dv + duk*dy) + t^2*duk*dv
                //   - dyk*dx - t*(dyk*du + dvk*dx) - t^2*dvk*du = 0
                // = (dxk*dy - dyk*dx) 
                //   + t*(dxk*dv + duk*dy - dyk*du - dvk*dx)
                //   + t^2*(duk*dv - dvk*du) = 0

                ll A = duk*dv - dvk*du;
                ll B = dxk*dv + duk*dy - dyk*du - dvk*dx;
                ll C = dxk*dy - dyk*dx;

                if (A == 0 && B == 0) {
                    if (C == 0) {
                        // Always collinear with i,j at any t
                        base++;
                    }
                    continue;
                }

                // Solve for t >= 0 rational.
                // We'll store as reduced fraction.
                if (A == 0) {
                    // B*t + C = 0 => t = -C/B
                    if (B == 0) continue;
                    // t = -C / B
                    ll num = -C;
                    ll den = B;
                    if (den < 0) { num = -num; den = -den; }
                    if (num < 0) continue; // t >= 0
                    ll g = gcd(abs(num), den);
                    num /= g;
                    den /= g;
                    cnt[{num, den}]++;
                } else {
                    // Solve quadratic: A*t^2 + B*t + C = 0
                    ll disc = B*B - 4*A*C;
                    if (disc < 0) continue;
                    ll sqrt_disc = (ll)round(sqrt((long double)disc));
                    if (sqrt_disc*sqrt_disc != disc) continue;

                    for (ll sign : {-1, 1}) {
                        ll num = -B + sign * sqrt_disc;
                        ll den = 2*A;
                        if (den < 0) { num = -num; den = -den; }
                        if (num < 0) continue;
                        // Check if t is rational integer (we require integer t? No, real t.)
                        // We'll store rational.
                        ll g = gcd(abs(num), den);
                        num /= g;
                        den /= g;
                        cnt[{num, den}]++;
                    }
                }
            }

            int best = base;
            for (auto &p : cnt) {
                best = max(best, base + p.second);
            }
            ans = max(ans, best);
        }
    }

    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Frac {
    ll a, b; // a / b, b > 0 ; special: b==0 means infinity
    bool inf;
    Frac(ll _a = 0, ll _b = 1, bool _inf = false) {
        if (_inf) {
            a = 1; b = 0; inf = true;
            return;
        }
        if (_b < 0) _a = -_a, _b = -_b;
        if (_a == 0) {
            a = 0; b = 1; inf = false;
        } else {
            ll g = std::gcd(std::llabs(_a), _b);
            a = _a / g;
            b = _b / g;
            inf = false;
        }
    }
    bool operator<(const Frac& other) const {
        if (inf != other.inf) return !inf && other.inf;
        if (inf) return false;
        __int128 lhs = (__int128)a * other.b;
        __int128 rhs = (__int128)other.a * b;
        return lhs < rhs;
    }
    bool operator==(const Frac& other) const {
        if (inf || other.inf) return inf == other.inf;
        return a == other.a && b == other.b;
    }
};

struct EventKey {
    Frac t;
    ll dx, dy; // normalized direction
    bool operator<(const EventKey& other) const {
        if (t < other.t) return true;
        if (other.t < t) return false;
        if (dx != other.dx) return dx < other.dx;
        return dy < other.dy;
    }
};

static inline pair<ll,ll> norm_dir(ll dx, ll dy) {
    if (dx == 0 && dy == 0) return {0, 0};
    ll g = std::gcd(std::llabs(dx), std::llabs(dy));
    dx /= g; dy /= g;
    if (dx < 0 || (dx == 0 && dy < 0)) dx = -dx, dy = -dy;
    return {dx, dy};
}

