#define MAXN 105
#define EPS 1e-9

int N;
double x[MAXN], y[MAXN], u[MAXN], v[MAXN];

int countCollinear(double t) {
    // For each pair, count using slope hashing - use O(N^2) approach
    int best = 1;
    for (int i = 0; i < N; i++) {
        double xi = x[i] + t*u[i], yi = y[i] + t*v[i];
        for (int j = i+1; j < N; j++) {
            double xj = x[j] + t*u[j], yj = y[j] + t*v[j];
            int cnt = 2;
            for (int k = 0; k < N; k++) {
                if (k == i || k == j) continue;
                double xk = x[k] + t*u[k], yk = y[k] + t*v[k];
                double cross = (xj-xi)*(yk-yi) - (yj-yi)*(xk-xi);
                if (fabs(cross) < EPS * (fabs(xj-xi)+fabs(yj-yi)+fabs(xk-xi)+fabs(yk-yi)+1))
                    cnt++;
            }
            if (cnt > best) best = cnt;
        }
    }
    return best;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll a, b, c; /* normalized line: a*x + b*y + c = 0 */
} Line;

typedef struct {
    ll x, y, u, v;
} Person;

static ll llabs2(ll x) { return x < 0 ? -x : x; }

static ll gcdll(ll a, ll b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a ? a : 1;
}

static int cmp_ll(const void *p1, const void *p2) {
    ll a = *(const ll *)p1;
    ll b = *(const ll *)p2;
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

static int cmp_line(const void *p1, const void *p2) {
    const Line *A = (const Line *)p1;
    const Line *B = (const Line *)p2;
    if (A->a != B->a) return (A->a < B->a) ? -1 : 1;
    if (A->b != B->b) return (A->b < B->b) ? -1 : 1;
    if (A->c != B->c) return (A->c < B->c) ? -1 : 1;
    return 0;
}

static Line make_line(ll x1, ll y1, ll x2, ll y2) {
    ll a = y2 - y1;
    ll b = x1 - x2;
    ll c = -(a * x1 + b * y1);

    ll g = gcdll(gcdll(a, b), c);
    a /= g; b /= g; c /= g;

    if (a < 0 || (a == 0 && b < 0) || (a == 0 && b == 0 && c < 0)) {
        a = -a; b = -b; c = -c;
    }

    Line L = {a, b, c};
    return L;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Person *p = (Person *)malloc((size_t)N * sizeof(Person));
    for (int i = 0; i < N; ++i) {
        scanf("%lld %lld %lld %lld", &p[i].x, &p[i].y, &p[i].u, &p[i].v);
    }

    if (N <= 2) {
        printf("%d\n", N);
        free(p);
        return 0;
    }

    int answer = 1;

    /* Case 1: same velocity group.
       Relative positions stay constant, so any collinear subset in one group
       is always shootable. */
    {
        /* Sort/group by velocity using simple O(N^2) marking because constraints are unknown.
           For each unprocessed person, collect same-velocity group. */
        int *used = (int *)calloc((size_t)N, sizeof(int));
        ll *keys = (ll *)malloc((size_t)N * sizeof(ll)); /* dummy reusable buffer */

        for (int i = 0; i < N; ++i) if (!used[i]) {
            int *idx = (int *)malloc((size_t)N * sizeof(int));
            int m = 0;
            for (int j = i; j < N; ++j) {
                if (!used[j] && p[j].u == p[i].u && p[j].v == p[i].v) {
                    used[j] = 1;
                    idx[m++] = j;
                }
            }

            if (m > answer) {
                if (m <= 2) {
                    if (m > answer) answer = m;
                } else {
                    Line *lines = (Line *)malloc((size_t)m * (m - 1) / 2 * sizeof(Line));
                    size_t cnt = 0;
                    for (int a = 0; a < m; ++a) {
                        for (int b = a + 1; b < m; ++b) {
                            int ia = idx[a], ib = idx[b];
                            if (p[ia].x == p[ib].x && p[ia].y == p[ib].y) continue;
                            lines[cnt++] = make_line(p[ia].x, p[ia].y, p[ib].x, p[ib].y);
                        }
                    }

                    if (cnt == 0) {
                        answer = m; /* all same position */
                    } else {
                        qsort(lines, cnt, sizeof(Line), cmp_line);
                        size_t l = 0;
                        while (l < cnt) {
                            size_t r = l + 1;
                            while (r < cnt &&
                                   lines[r].a == lines[l].a &&
                                   lines[r].b == lines[l].b &&
                                   lines[r].c == lines[l].c) r++;
                            /* if k points on same line, number of pairs is C(k,2) */
                            size_t pairs = r - l;
                            int k = 2;
                            while ((size_t)k * (k - 1) / 2 < pairs) k++;
                            if ((size_t)k * (k - 1) / 2 == pairs && k > answer) answer = k;
                            l = r;
                        }
                    }
                    free(lines);
                }
            }
            free(idx);
        }
        free(keys);
        free(used);
    }

    /* Case 2: different velocities.
       For apples i,j,k to be collinear at some time t:
       cross((Pj-Pi)+t(Vj-Vi), (Pk-Pi)+t(Vk-Vi)) = 0
       This is a quadratic in t. Any optimal line with >=2 apples at time t
       is determined by some pair at that time, so enumerate candidate times
       from triples and test all points. Also include t=0. */

    /* test t=0 */
    {
        for (int i = 0; i < N; ++i) {
            int same = 0;
            Line *lines = (Line *)malloc((size_t)(N - 1) * sizeof(Line));
            int cnt = 0;
            for (int j = 0; j < N; ++j) if (j != i) {
                ll dx = p[j].x - p[i].x;
                ll dy = p[j].y - p[i].y;
                if (dx == 0 && dy == 0) {
                    same++;
                } else {
                    ll g = gcdll(dx, dy);
                    dx /= g; dy /= g;
                    if (dx < 0 || (dx == 0 && dy < 0)) {
                        dx = -dx; dy = -dy;
                    }
                    lines[cnt++] = (Line){dx, dy, 0};
                }
            }
            qsort(lines, cnt, sizeof(Line), cmp_line);
            int bestdir = 0;
            for (int l = 0; l < cnt; ) {
                int r = l + 1;
                while (r < cnt && lines[r].a == lines[l].a && lines[r].b == lines[l].b) r++;
                if (r - l > bestdir) bestdir = r - l;
                l = r;
            }
            if (1 + same + bestdir > answer) answer = 1 + same + bestdir;
            free(lines);
        }
    }

    /* collect candidate times as reduced fractions num/den, num>=0, den>0 */
    typedef struct { ll num, den; } Frac;
    Frac *cand = NULL;
    size_t cand_sz = 0, cand_cap = 0;

    #define ADD_CAND(NUM, DEN) do { \
        ll _num = (NUM), _den = (DEN); \
        if (_den < 0) { _den = -_den; _num = -_num; } \
        if (_num >= 0 && _den != 0) { \
            ll _g = gcdll(_num, _den); \
            _num /= _g; _den /= _g; \
            if (cand_sz == cand_cap) { \
                cand_cap = cand_cap ? cand_cap * 2 : 1024; \
                cand = (Frac *)realloc(cand, cand_cap * sizeof(Frac)); \
            } \
            cand[cand_sz++] = (Frac){_num, _den}; \
        } \
    } while (0)

    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            for (int k = j + 1; k < N; ++k) {
                ll ax = p[j].x - p[i].x, ay = p[j].y - p[i].y;
                ll bx = p[k].x - p[i].x, by = p[k].y - p[i].y;
                ll ux = p[j].u - p[i].u, uy = p[j].v - p[i].v;
                ll vx = p[k].u - p[i].u, vy = p[k].v - p[i].v;

                ll A = ux * vy - uy * vx;
                ll B = ax * vy + ux * by - ay * vx - uy * bx;
                ll C = ax * by - ay * bx;

                if (A == 0) {
                    if (B == 0) {
                        /* always collinear or never; t=0 already covered */
                    } else {
                        ADD_CAND(-C, B);
                    }
                } else {
                    /* integer roots only if discriminant is perfect square */
                    long double Dd = (long double)B * (long double)B - 4.0L * (long double)A * (long double)C;
                    if (Dd < 0) continue;
                    ll D = B * B - 4 * A * C;
                    if (D < 0) continue;
                    ll s = 0;
                    while ((s + 1) <= 3037000499LL && (s + 1) * (s + 1) <= D) s++;
                    while (s * s > D) s--;
                    if (s * s != D) continue;
                    ADD_CAND(-B + s, 2 * A);
                    ADD_CAND(-B - s, 2 * A);
                }
            }
        }
    }

    /* sort/unique candidate fractions */
    if (cand_sz > 0) {
        int cmp_frac(const void *p1, const void *p2) {
            const Frac *A = (const Frac *)p1;
            const Frac *B = (const Frac *)p2;
            if (A->num != B->num) return (A->num < B->num) ? -1 : 1;
            if (A->den != B->den) return (A->den < B->den) ? -1 : 1;
            return 0;
        }
        qsort(cand, cand_sz, sizeof(Frac), cmp_frac);

        size_t uniq = 0;
        for (size_t i = 0; i < cand_sz; ++i) {
            if (uniq == 0 || cand[i].num != cand[uniq - 1].num || cand[i].den != cand[uniq - 1].den) {
                cand[uniq++] = cand[i];
            }
        }
        cand_sz = uniq;

        for (size_t id = 0; id < cand_sz; ++id) {
            ll tn = cand[id].num, td = cand[id].den;

            for (int i = 0; i < N; ++i) {
                int same = 0;
                Line *dirs = (Line *)malloc((size_t)(N - 1) * sizeof(Line));
                int cnt = 0;

                ll xi_num = p[i].x * td + p[i].u * tn;
                ll yi_num = p[i].y * td + p[i].v * tn;

                for (int j = 0; j < N; ++j) if (j != i) {
                    ll xj_num = p[j].x * td + p[j].u * tn;
                    ll yj_num = p[j].y * td + p[j].v * tn;

                    ll dx = xj_num - xi_num;
                    ll dy = yj_num - yi_num;
                    if (dx == 0 && dy == 0) {
                        same++;
                    } else {
                        ll g = gcdll(dx, dy);
                        dx /= g; dy /= g;
                        if (dx < 0 || (dx == 0 && dy < 0)) {
                            dx = -dx; dy = -dy;
                        }
                        dirs[cnt++] = (Line){dx, dy, 0};
                    }
                }

                qsort(dirs, cnt, sizeof(Line), cmp_line);
                int bestdir = 0;
                for (int l = 0; l < cnt; ) {
                    int r = l + 1;
                    while (r < cnt && dirs[r].a == dirs[l].a && dirs[r].b == dirs[l].b) r++;
                    if (r - l > bestdir) bestdir = r - l;
                    l = r;
                }

                if (1 + same + bestdir > answer) answer = 1 + same + bestdir;
                free(dirs);
            }
        }
    }

    printf("%d\n", answer);

    free(cand);
    free(p);
    return 0;
}
